DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='record_directory_event'; def:=replace(def,'THEN payload->>''source'' ELSE','THEN coalesce(payload->>''source'','''') ELSE'); def:=replace(def,'THEN payload->>''medium'' ELSE','THEN coalesce(payload->>''medium'','''') ELSE'); def:=replace(def,'THEN payload->>''campaign'' ELSE','THEN coalesce(payload->>''campaign'','''') ELSE'); EXECUTE def;
SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='lead_operations_action'; def:=replace(def,'END; $function$','PERFORM set_config(''app.lead_operations'','''',true); END; $function$'); EXECUTE def; END $$;